import{c as a,Q as r,j as t,m as o}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"CompressKV: Semantic-Retrieval-Guided KV-Cache Compression for Resource-Efficient Long-Context LLM Inference","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.24467","title":"CompressKV: Semantic-Retrieval-Guided KV-Cache Compression for Resource-Efficient Long-Context LLM Inference","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.24467,"authors":["Xiaolin Lin","Jingcun Wang","Olga Kondrateva","Yiyu Shi","Bing Li","Grace Li Zhang"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2606.24467v1","pdf_path":"pdfs/2606.24467.pdf","published_date":"2026-06-23T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-23-compresskv-semantic-retrieval-kv-cache-compression-2606-24467.md","filePath":"research/papers/2026-06-23-compresskv-semantic-retrieval-kv-cache-compression-2606-24467.md","lastUpdated":1785909234000}'),i={name:"research/papers/2026-06-23-compresskv-semantic-retrieval-kv-cache-compression-2606-24467.md"};function s(n,e,c,l,d,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="compresskv-semantic-retrieval-guided-kv-cache-compression-for-resource-efficient-long-context-llm-inference" tabindex="-1">CompressKV: Semantic-Retrieval-Guided KV-Cache Compression for Resource-Efficient Long-Context LLM Inference <a class="header-anchor" href="#compresskv-semantic-retrieval-guided-kv-cache-compression-for-resource-efficient-long-context-llm-inference" aria-label="Permalink to &quot;CompressKV: Semantic-Retrieval-Guided KV-Cache Compression for Resource-Efficient Long-Context LLM Inference&quot;">​</a></h1><p><strong>Authors</strong>: Xiaolin Lin, Jingcun Wang, Olga Kondrateva, Yiyu Shi, Bing Li, Grace Li Zhang <strong>Published</strong>: June 23, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.24467" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.24467</a> · <a href="https://arxiv.org/html/2606.24467v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.24467 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.24467" target="_blank" rel="noreferrer">research/papers/pdfs/2606.24467.pdf</a> (14 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Long-context large language model (LLM) inference is increasingly constrained by the memory footprint and decoding cost of key-value (KV) caches, limiting sustainable deployment on resource-constrained hardware. Existing KV cache eviction methods typically apply heuristic token scoring over all heads in GQA-based LLMs. These methods ignore the different functionalities of attention heads, leading to the eviction of critical tokens and thus degrading the performance of LLMs. To address this issue, we propose CompressKV, a resource-efficient KV-cache compression framework for GQA-based LLMs. Instead of aggregating attention scores from all heads, CompressKV identifies Semantic Retrieval Heads (SRHs) that capture both the initial and final tokens of a prompt and semantically important mid-context evidence, and uses them to select tokens whose KV pairs should be retained. Furthermore, CompressKV allocates cache budgets across layers according to offline estimates of layer-wise eviction error. Experiments on LongBench and Needle-in-a-Haystack show that CompressKV consistently outperforms existing KV-cache eviction methods across memory budgets. Notably, it preserves over 97% of full-cache performance using only 3% of the KV cache on LongBench question-answering tasks and achieves 90% accuracy with just 0.7% KV storage on Needle-in-a-Haystack. These results demonstrate an improved resource–performance trade-off for long-context LLM inference.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 CompressKV，針對 GQA-based LLM 的 KV cache 壓縮框架，核心機制是識別 Semantic Retrieval Heads（SRHs）</li><li>SRHs 能捕捉 prompt 的首尾 token 與語義重要的中段 evidence，用以決定哪些 KV pair 應保留，取代對所有 attention heads 平均聚合的啟發式做法</li><li>採用 layer-wise 離線估算 eviction error，跨層非均勻分配 cache budget，避免一刀切的均等壓縮</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>LongBench QA 任務：僅用 3% KV cache，保留超過 97% 全快取效能</li><li>Needle-in-a-Haystack：僅用 0.7% KV storage，仍達 90% 準確率</li><li>在多種 memory budget 下一致優於現有 KV cache eviction 方法</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>論文未設獨立 Limitations 章節</li><li>SRHs 識別方式為 offline 估算，推理時若 prompt 分布偏移（out-of-distribution），layer budget 分配可能次優</li><li>實驗集中於 LongBench 與 Needle-in-a-Haystack，對話、程式碼等其他長 context 場景的泛化能力未充分驗證</li><li>結果針對 GQA-based LLM，對 MHA 或 MLA 架構的適用性未說明</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>context-management / token budget</strong>：CompressKV 的 3% KV cache 保留 97% 效能，直接對應 context-management.md 的 NLAH 原則（Right context &gt; more context）；SRH 選擇語義重要 token 的機制，本質上與「只放 HEAD/TAIL 最重要資訊」的 context 放置策略同構。</li><li><strong>KV cache 與 prefix caching 的邊界</strong>：Workspace 已有 <code>2026-01-19-prefix-cache-to-fusion-rag-cache-2601-12904.md</code> 與 <code>2026-05-28-cacheprobe-auditing-prompt-cache-isolation-2605-30613.md</code>；CompressKV 聚焦 decode 階段 KV eviction（非 prefill prefix reuse），與 prompt caching 層次不同，可互補而非重疊。⚠️ 落地需確認目標推理框架（vLLM/SGLang）是否支援 GQA head-level KV 過濾介面。</li><li><strong>unverified_success 閘門</strong>：論文以 LLM benchmark 分數自報效能，符合 core.md 的 unverified_success 警示——直接採信前應在目標 serving stack 親跑 healthcheck，而非僅引用論文數字。</li><li><strong>RAG / retrieval 相關論文群</strong>：SRHs 識別「語義重要 mid-context evidence」的邏輯與 RAG 的 chunk relevance scoring 高度相似；可對照 <code>2024-05-23-hipporag-neurobiological-memory-2405-14831.md</code> 探討記憶檢索與 attention head 分工的關係。⚠️ 跨論文整合屬 off-rails 推斷，需人工判斷。</li></ul>',16)])])}const g=a(i,[["render",s]]);export{p as __pageData,g as default};
